{
  "name": "@grugs/opencode-debug",
  "version": "1.6.5",
  "description": "Language-agnostic HTTP debugging and live logs for OpenCode v2 with ngrok tunneling support",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "debug",
    "debugging",
    "ngrok",
    "plugin"
  ],
  "homepage": "https://github.com/BrianGrug/opencode-debug#readme",
  "bugs": {
    "url": "https://github.com/BrianGrug/opencode-debug/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/BrianGrug/opencode-debug.git"
  },
  "license": "MIT",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./rpc": {
      "types": "./dist/rpc.d.ts",
      "import": "./dist/rpc.js"
    }
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "files": [
    "dist",
    "index.ts",
    "tui.ts"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build": "bun run scripts/build.ts && tsc --emitDeclarationOnly --declaration --outDir dist",
    "prepublishOnly": "bun run build"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.28",
    "@ngrok/ngrok": "^1.4.1"
  },
  "devDependencies": {
    "@opentui/core": "^0.6.3",
    "@opentui/solid": "^0.6.3",
    "@types/bun": "latest",
    "@types/node": "latest",
    "solid-js": "1.9.12",
    "typescript": "^5.7.3"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  },
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public"
  },
  "$schema": "https://json.schemastore.org/package.json",
  "module": "./dist/index.js"
}
